{"sql": "SELECT species_scientific_name, species_common_name FROM `bigquery-public-data.new_york.tree_species` WHERE UPPER(species_scientific_name) NOT IN (
  SELECT UPPER(spc_latin) FROM `bigquery-public-data.new_york.tree_census_1995` WHERE spc_latin IS NOT NULL AND spc_latin != ''
  UNION
  SELECT UPPER(spc_latin) FROM `bigquery-public-data.new_york.tree_census_2015` WHERE spc_latin IS NOT NULL AND spc_latin != ''
) LIMIT 10"}

{"sql": "SELECT species_scientific_name, species_common_name FROM `bigquery-public-data.new_york.tree_species` WHERE UPPER(species_scientific_name) NOT IN (
  SELECT DISTINCT UPPER(spc_latin) FROM `bigquery-public-data.new_york.tree_census_1995` WHERE spc_latin IS NOT NULL AND spc_latin != ''
  UNION ALL
  SELECT DISTINCT UPPER(spc_latin) FROM `bigquery-public-data.new_york.tree_census_2015` WHERE spc_latin IS NOT NULL AND spc_latin != ''
) LIMIT 10"}
